import React, { useState } from 'react';
import './CSS/AdminDashboard.css';
import { Link } from 'react-router-dom';

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');

  // Separated User State Data (Buyers)
  const [users, setUsers] = useState([
    { 
      id: '#USR-101', 
      name: 'Mona', 
      email: 'mona@gmail.com', 
      phone: '+91 98765 43210',
      status: 'Active', 
      joined: '2026-02-14',
      activities: [
        { date: '2026-03-08 16:05', action: 'Placed an order #ORD-991' },
        { date: '2026-03-08 12:30', action: 'Logged in successfully' },
        { date: '2026-02-14 11:45', action: 'Created account' }
      ]
    },
    { 
      id: '#USR-102', 
      name: 'Jhanvi', 
      email: 'jhanvi@gmail.com', 
      phone: '+91 98123 45678',
      status: 'Active', 
      joined: '2026-03-01',
      activities: [
        { date: '2026-03-05 18:22', action: 'Added items to cart' },
        { date: '2026-03-01 08:30', action: 'Created account' }
      ]
    }
  ]);

  // Separated Seller State Data (Vendors/Stores)
  const [sellers, setSellers] = useState([
    { 
      id: '#SLR-201', 
      storeName: 'Apex Electronics', 
      ownerName: 'Anisha', 
      email: 'apexelectronics@seller.com', 
      phone: '+91 91234 56789',
      status: 'Active', 
      joined: '2026-02-10',
      activities: [
        { date: '2026-03-08 14:20', action: 'Listed new product: "Wireless Headphones"' },
        { date: '2026-03-07 10:15', action: 'Fulfilled Order #ORD-882' },
        { date: '2026-02-10 09:00', action: 'Seller account registered and verified' }
      ]
    },
    { 
      id: '#SLR-202', 
      storeName: 'TechPulse Digital', 
      ownerName: 'Bharath', 
      email: 'techpulse@seller.com', 
      phone: '+91 90000 11122',
      status: 'Blocked', 
      joined: '2026-03-05',
      activities: [
        { date: '2026-03-07 15:10', action: 'Account flagged for high cancellation rate' },
        { date: '2026-03-05 13:00', action: 'Seller account registered' }
      ]
    }
  ]);

  // Handlers to toggle status
  const toggleUserStatus = (id) => {
    setUsers(users.map(u => u.id === id ? { ...u, status: u.status === 'Active' ? 'Blocked' : 'Active' } : u));
  };

  const toggleSellerStatus = (id) => {
    setSellers(sellers.map(s => s.id === id ? { ...s, status: s.status === 'Active' ? 'Blocked' : 'Active' } : s));
  };

  const renderContent = () => {
    switch (activeTab) {
      // 1. OVERVIEW TAB
      case 'overview':
        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>System Analytics & Overview</h2>
              <p className="panel-subtitle">Live system performance and platform status</p>
            </div>

            <div className="stats-cards">
              <div className="card border-blue">
                <div className="card-info">
                  <h3>Total Users</h3>
                  <p className="card-value">{users.length}</p>
                </div>
              </div>
              <div className="card border-purple">
                <div className="card-info">
                  <h3>Total Sellers</h3>
                  <p className="card-value">{sellers.length}</p>
                </div>
              </div>
              <div className="card border-green">
                <div className="card-info">
                  <h3>Active Accounts</h3>
                  <p className="card-value">
                    {users.filter(u => u.status === 'Active').length + sellers.filter(s => s.status === 'Active').length}
                  </p>
                </div>
              </div>
              <div className="card border-red">
                <div className="card-info">
                  <h3>Blocked Accounts</h3>
                  <p className="card-value">
                    {users.filter(u => u.status === 'Blocked').length + sellers.filter(s => s.status === 'Blocked').length}
                  </p>
                </div>
              </div>
            </div>

            <div className="overview-sections">
              <div className="overview-box">
                <h3>Quick Platform Metrics</h3>
                <p><strong>Active Ratio:</strong> {Math.round(((users.filter(u => u.status === 'Active').length + sellers.filter(s => s.status === 'Active').length) / (users.length + sellers.length)) * 100)}% active accounts</p>
                <p><strong>Buyer/Seller Ratio:</strong> {users.length} Users : {sellers.length} Sellers</p>
              </div>
            </div>
          </div>
        );

      // 2. USER DETAILS TAB
      case 'user-details':
        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>User Details</h2>
              <p className="panel-subtitle">Manage customer profile accounts and access permissions</p>
            </div>
            <div className="audit-card">
              <div className="audit-table-wrapper">
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>User ID</th>
                      <th>Name</th>
                      <th>Email</th>
                      <th>Phone</th>
                      <th>Joined Date</th>
                      <th>Status</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.map(user => (
                      <tr key={user.id}>
                        <td><span className="user-id">{user.id}</span></td>
                        <td className="font-semibold">{user.name}</td>
                        <td className="text-muted">{user.email}</td>
                        <td>{user.phone}</td>
                        <td>{user.joined}</td>
                        <td><span className={`badge ${user.status.toLowerCase()}`}>{user.status}</span></td>
                        <td>
                          <button 
                            className={`action-btn ${user.status === 'Active' ? 'block' : 'grant'}`}
                            onClick={() => toggleUserStatus(user.id)}
                          >
                            {user.status === 'Active' ? 'Block' : 'Unblock'}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        );

      // 3. USER ACTIVITY TAB
      case 'user-activity':
        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>User Activity</h2>
              <p className="panel-subtitle">Individual action streams and activity histories for users</p>
            </div>
            {users.map(user => (
              <div className="activity-block-card" key={user.id}>
                <h3>{user.name} <span>({user.id})</span></h3>
                <ul className="activity-list">
                  {user.activities.map((act, idx) => (
                    <li key={idx}>
                      <span className="activity-date">[{act.date}]</span> {act.action}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        );

      // 4. SELLER DETAILS TAB
      case 'seller-details':
        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>Seller Details</h2>
              <p className="panel-subtitle">Manage registered stores and vendor permissions</p>
            </div>
            <div className="audit-card">
              <div className="audit-table-wrapper">
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>Seller ID</th>
                      <th>Store Name</th>
                      <th>Owner Name</th>
                      <th>Email</th>
                      <th>Phone</th>
                      <th>Status</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sellers.map(seller => (
                      <tr key={seller.id}>
                        <td><span className="user-id seller-id">{seller.id}</span></td>
                        <td className="font-semibold">{seller.storeName}</td>
                        <td>{seller.ownerName}</td>
                        <td className="text-muted">{seller.email}</td>
                        <td>{seller.phone}</td>
                        <td><span className={`badge ${seller.status.toLowerCase()}`}>{seller.status}</span></td>
                        <td>
                          <button 
                            className={`action-btn ${seller.status === 'Active' ? 'block' : 'grant'}`}
                            onClick={() => toggleSellerStatus(seller.id)}
                          >
                            {seller.status === 'Active' ? 'Block Store' : 'Approve Store'}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        );

      // 5. SELLER ACTIVITY TAB
      case 'seller-activity':
        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>Seller Activity</h2>
              <p className="panel-subtitle">Product updates, order fulfillments, and seller operations</p>
            </div>
            {sellers.map(seller => (
              <div className="activity-block-card" key={seller.id}>
                <h3>{seller.storeName} <span>({seller.id} - Owner: {seller.ownerName})</span></h3>
                <ul className="activity-list">
                  {seller.activities.map((act, idx) => (
                    <li key={idx}>
                      <span className="activity-date">[{act.date}]</span> {act.action}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        );

      // 6. AUDIT LOG TAB
      case 'audit-log': {
        const userLogs = users.flatMap(u => 
          u.activities.map(act => ({ ...act, name: u.name, role: 'User', id: u.id }))
        );
        const sellerLogs = sellers.flatMap(s => 
          s.activities.map(act => ({ ...act, name: s.storeName, role: 'Seller', id: s.id }))
        );
        const allLogs = [...userLogs, ...sellerLogs];

        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>Audit Log</h2>
              <p className="panel-subtitle">Combined system logs across all users and sellers</p>
            </div>

            <div className="audit-card">
              <div className="audit-table-wrapper">
                <table className="audit-table">
                  <thead>
                    <tr>
                      <th>Role</th>
                      <th>Account</th>
                      <th>Action Performed</th>
                      <th className="text-right">Timestamp</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allLogs.map((log, idx) => (
                      <tr key={idx}>
                        <td>
                          <span className={`role-badge ${log.role.toLowerCase()}`}>
                            {log.role}
                          </span>
                        </td>
                        <td>
                          <span className="user-name">{log.name}</span>
                          <span className="user-id"> ({log.id})</span>
                        </td>
                        <td className="log-action-text">{log.action}</td>
                        <td className="text-right log-time">{log.date}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        );
      }

      default:
        return null;
    }
  };

  return (
    <div className="admin-standalone-container">
      {/* Top Admin Navigation Header */}
      <header className="admin-topbar">
        <div className="admin-brand">
          <h2>HEX<span>CART</span> <small>Admin Portal</small></h2>
        </div>
        <div className="admin-actions">
          <Link to="/" className="btn-storefront">Return to Store</Link>
          <button onClick={() => { localStorage.clear(); window.location.replace('/'); }} className="btn-logout">
            Logout
          </button>
        </div>
      </header>

      <div className="admin-layout">
        {/* Side Panel Navigation */}
        <aside className="admin-sidebar">
          <nav className="sidebar-menu">
            <button className={activeTab === 'overview' ? 'active' : ''} onClick={() => setActiveTab('overview')}>
              Overview
            </button>
            <button className={activeTab === 'user-details' ? 'active' : ''} onClick={() => setActiveTab('user-details')}>
              User Details
            </button>
            <button className={activeTab === 'user-activity' ? 'active' : ''} onClick={() => setActiveTab('user-activity')}>
              User Activity
            </button>
            <button className={activeTab === 'seller-details' ? 'active' : ''} onClick={() => setActiveTab('seller-details')}>
              Seller Details
            </button>
            <button className={activeTab === 'seller-activity' ? 'active' : ''} onClick={() => setActiveTab('seller-activity')}>
              Seller Activity
            </button>
            <button className={activeTab === 'audit-log' ? 'active' : ''} onClick={() => setActiveTab('audit-log')}>
              Audit Log
            </button>
          </nav>
        </aside>

        {/* Main Panel Content Area */}
        <main className="admin-content">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

export default AdminDashboard;
